readme_description:
Given a `node` in a binary search tree, return the in-order successor of that node in the BST. If that node has no in-order successor, return `null`.

The successor of a `node` is the node with the smallest key greater than `node.val`.

You will have direct access to the node but not to the root of the tree. Each node will have a reference to its parent node. Below is the definition for `Node`:

```
class Node {
    public int val;
    public Node left;
    public Node right;
    public Node parent;
}
```

**Follow up:** Could you solve it without looking up any of the node's values?

helpers_content:
class TreeNodeP:
    def __init__(self, val: int = 0) -> None:
        self.val = val
        self.left: TreeNodeP | None = None
        self.right: TreeNodeP | None = None
        self.parent: TreeNodeP | None = None


def build_parent_tree(vals: list[int | None]) -> TreeNodeP | None:
    if not vals:
        return None
    v0 = vals[0]
    assert v0 is not None
    root = TreeNodeP(v0)
    queue: list[TreeNodeP] = [root]
    i = 1
    while queue and i < len(vals):
        node = queue.pop(0)
        if i < len(vals):
            v = vals[i]
            i += 1
            if v is not None:
                child = TreeNodeP(v)
                child.parent = node
                node.left = child
                queue.append(child)
        if i < len(vals):
            v = vals[i]
            i += 1
            if v is not None:
                child = TreeNodeP(v)
                child.parent = node
                node.right = child
                queue.append(child)
    return root


def find_node(root: TreeNodeP | None, val: int) -> TreeNodeP | None:
    if root is None:
        return None
    if root.val == val:
        return root
    return find_node(root.left, val) or find_node(root.right, val)

